private void devices(HttpExchange exchange) throws IOException {
    requireAuthenticated(exchange);
    String[] parts = exchange.getRequestURI().getPath().split("/");
    if (parts.length == 4 && "GET".equals(exchange.getRequestMethod())) {
        json(exchange, 200, Map.of("devices", devices.devices().stream().map(device -> Map.of(
                "deviceId", device.deviceId(), "role", device.role())).toList()));
        return;
    }
    if (parts.length == 5 && "DELETE".equals(exchange.getRequestMethod())) {
        devices.revoke(decodePath(parts[4]));
        json(exchange, 200, Map.of("revoked", true));
        return;
    }
    throw notFound(exchange.getRequestURI().getPath());
}

